// Builds lib/ui/host_system_marks.g.dart, the outlines HostSystemIcon paints
// for an identified operating system, from tool/host_system_marks/*.svg and
// marks.json next to them. Run from apps/client after changing either:
//
//   dart run tool/host_system_marks.dart
//
// The outlines are the single-path, 24-unit marks of the Simple Icons
// project (CC0, https://simpleicons.org; version in [simpleIconsVersion]),
// copied unchanged; the names and logos remain trademarks of their owners and
// are used only to tell the user which system a Host runs. The generated file
// is checked in; test/host_system_marks_test.dart fails when it is stale.
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;

const hostSystemMarksPath = 'lib/ui/host_system_marks.g.dart';
const simpleIconsVersion = '13.21.0';

/// Brand colours are kept in hue but brought into a lightness range that
/// reads on both the light and the dark card surface (several brands are
/// black or near-black).
int displayColor(String hex) {
  final r = int.parse(hex.substring(0, 2), radix: 16) / 255;
  final g = int.parse(hex.substring(2, 4), radix: 16) / 255;
  final b = int.parse(hex.substring(4, 6), radix: 16) / 255;
  final high = math.max(r, math.max(g, b)), low = math.min(r, math.min(g, b));
  var lightness = (high + low) / 2;
  final delta = high - low;
  var saturation = 0.0, hue = 0.0;
  if (delta > 0) {
    saturation = delta / (1 - (2 * lightness - 1).abs());
    if (high == r) {
      hue = ((g - b) / delta) % 6;
    } else if (high == g) {
      hue = (b - r) / delta + 2;
    } else {
      hue = (r - g) / delta + 4;
    }
    hue *= 60;
  }
  // Greys (no hue) become the neutral slate used for other plain marks.
  if (saturation < .08) {
    saturation = .12;
    hue = 205;
    lightness = .62;
  }
  lightness = lightness.clamp(.52, .66);
  saturation = math.min(saturation, .78);
  final chroma = (1 - (2 * lightness - 1).abs()) * saturation;
  final second = chroma * (1 - ((hue / 60) % 2 - 1).abs());
  final base = lightness - chroma / 2;
  final (double cr, double cg, double cb) = switch (hue ~/ 60 % 6) {
    0 => (chroma, second, 0),
    1 => (second, chroma, 0),
    2 => (0, chroma, second),
    3 => (0, second, chroma),
    4 => (second, 0, chroma),
    _ => (chroma, 0, second),
  };
  int channel(double v) => ((v + base) * 255).round().clamp(0, 255);
  return 0xff000000 | channel(cr) << 16 | channel(cg) << 8 | channel(cb);
}

String buildHostSystemMarks(Directory source) {
  final manifest = jsonDecode(
    File('${source.path}/marks.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final names = manifest.keys.toList()..sort();
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/host_system_marks.dart. Do not edit.')
    ..writeln('//')
    ..writeln('// Outlines: Simple Icons $simpleIconsVersion (CC0), unchanged.')
    ..writeln('// Names and logos are trademarks of their respective owners.')
    ..writeln('// dart format off')
    ..writeln()
    ..writeln('/// Mark name -> display colour (ARGB) and SVG path data on a')
    ..writeln('/// 24-unit canvas.')
    ..writeln('const hostSystemMarks = <String, ({int color, String path})>{');
  for (final name in names) {
    if (!RegExp(r'^[a-z][a-z0-9]*$').hasMatch(name)) {
      throw FormatException('Bad mark name $name');
    }
    final svg = File('${source.path}/$name.svg').readAsStringSync();
    final paths = RegExp(r'<path d="([^"]+)"').allMatches(svg).toList();
    if (paths.length != 1 || !svg.contains('viewBox="0 0 24 24"')) {
      throw FormatException('$name.svg is not a single 24-unit path');
    }
    final data = paths.single.group(1)!;
    if (!RegExp(r'^[MmLlHhVvCcSsQqTtAaZz0-9eE.,+\- ]+$').hasMatch(data)) {
      throw FormatException('$name.svg has unexpected path data');
    }
    final entry = manifest[name] as Map<String, dynamic>;
    final color = displayColor(entry['hex'] as String);
    out
      ..writeln('  // ${entry['title']}')
      ..writeln(
        "  '$name': (color: 0x${color.toRadixString(16)}, path: '$data'),",
      );
  }
  out.writeln('};');
  return out.toString();
}

void main() {
  File(hostSystemMarksPath).writeAsStringSync(
    buildHostSystemMarks(Directory('tool/host_system_marks')),
  );
}
